INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('LIC Landing', 'lic-landing-rooftop', 'Secret Rooftop in Queens With Zero Tourists', 'Long Island City', 'queens', 'rooftop', 'Free skyline views over Manhattan, cold drinks in hand, and almost zero tourist energy. LIC Landing feels like a locals-only secret right on the waterfront.', 'Free skyline views over Manhattan, cold drinks in hand, and almost zero tourist energy.', 'Arrive 30 to 45 minutes before sunset and head straight for the railing. It gets windy once the sun drops, so bring a light jacket.', 'Take the 7 train to Vernon Blvd–Jackson Ave, then a quick 10-minute walk toward the water.', 'After the sunset, stroll the beautiful Gantry Plaza waterfront path. Then grab a great coffee or late bite at Sweetleaf. It is right nearby and way better than anything in Midtown.', 'Weekday sunsets from May through October', 'Weekend afternoons in peak summer — it gets packed', 'Free entry. Drinks and food cost extra if you stay for a round.', '["skyline-views","chill","waterfront","free","sunset"]', 2, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=LIC+Landing+Long+Island+City+NYC', 'https://commons.wikimedia.org/wiki/Special:FilePath/45-45_Center_Boulevard%2C_Long_Island_City%2C_New_York%2C_USA_-_Tower_against_cloudy_skyline.jpg', NULL, 1, 1775699485813, 1775699485813);
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('Paulie Gee''s Slice Shop', 'best-slice-brooklyn-after-midnight', 'Best Slice in Brooklyn After Midnight', 'Greenpoint', 'brooklyn', 'pizza', 'Craving pizza at 1 a.m. after a night out? Skip the sad Manhattan slices and head to Paulie Gee''s Slice Shop in Greenpoint. Their square Sicilian-style slices are crispy, cheesy, and actually worth the trip.', 'Square Sicilian slices that are actually worth the late-night detour.', 'Go late on weekends when they stay open until 2 a.m. Cash is king and the line moves fast once the bars let out. Try the Hellboy if you like hot honey and pepperoni.', 'G to Greenpoint Ave or L to Bedford Ave, then a short walk. Address: 110 Franklin St, Brooklyn.', 'Grab a nightcap at one of the dive bars nearby or walk over to L''Industrie if you want thin-crust instead.', 'Late on weekends, especially after midnight', 'Saturday right after the bars let out if you hate waiting for your slice', 'Cheap enough to do two slices and keep moving.', '["late-night","pizza","cheap","locals"]', 1, NULL, NULL, NULL, NULL, NULL, 1, 1775699485813, 1775699485813);
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('St. Nick''s Pub', 'free-jazz-nights-harlem-locals-love', 'Free Jazz Nights Harlem Locals Love', 'Harlem', 'manhattan', 'bar', 'Most jazz in Manhattan costs $20+ cover and feels like a tourist show. Head up to Harlem for the real thing - intimate sessions where locals actually hang out and musicians rotate in.', 'Free-ish Harlem jazz nights that still feel local instead of staged.', 'Wednesday nights are the move. Show up early, sit at the bar, and order the jerk chicken - it''s cheap and excellent.', '3 train to 149th Street or A/B/C/D to 145th or 155th. The spot sits right in the heart of Sugar Hill.', 'Grab a late slice or Dominican food from the spots right next door after the set ends.', 'Wednesday nights', 'Late Fridays if you want the music without a packed room', 'Easy to keep the whole night under $20 if you keep it simple.', '["jazz","free","locals","authentic"]', 2, NULL, NULL, NULL, NULL, NULL, 1, 1775699485813, 1775699485813);
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('Los Tacos No. 1', 'los-tacos-no-1-chelsea', 'The Only Taco Spot in Manhattan Worth Standing in Line For', 'Chelsea', 'manhattan', 'food', 'Los Tacos No. 1 started inside Chelsea Market and became the kind of place where the line itself is part of the experience. The corn tortillas are made fresh right in front of you — you can hear them slapping the press — and the adobada is legitimately some of the best in the city. It''s a counter-service operation, no frills, just excellent tacos.
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('Bemelmans Bar', 'bemelmans-bar-upper-east-side', 'The Most Beautiful Bar in New York That Nobody Under 30 Knows About', 'Upper East Side', 'manhattan', 'bar', 'Bemelmans Bar inside The Carlyle hotel is the kind of place that makes you sit up straighter. The walls are covered in murals by Ludwig Bemelmans — the guy who created Madeline — and they''ve been there since 1947. There''s live jazz most nights, the lighting is the color of honey, and the bartenders wear white jackets. It''s old New York in the best possible way.
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('Devoción', 'devocion-williamsburg', '3-Story Coffee Temple in Williamsburg With a Living Wall', 'Williamsburg', 'brooklyn', 'coffee', 'Devoción takes the idea of a third-wave coffee shop and turns it into something that feels almost sacred. The Williamsburg flagship is three stories of exposed brick, towering ceilings, and an actual living wall of tropical plants climbing up the back. The beans come direct from Colombia — they roast on-site — and you can taste the difference. Their pour-over is exceptional.
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('Birria-Landia', 'birria-landia-jackson-heights', 'Food Truck Birria Tacos That Are Worth the Trip to Queens', 'Jackson Heights', 'queens', 'food', 'Birria-Landia is a food truck that became a phenomenon. Parked on Roosevelt Ave in Jackson Heights, it serves birria tacos — slow-braised beef in a rich, red consommé — that are crispy, cheesy, and dripping with flavor. You dip them in the broth and it''s one of those eating experiences that recalibrates your standards for what a taco can be.
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('Utopia Bagels', 'best-bagel-nyc-not-ess-a-bagel', 'Best Bagel in NYC That Isn''t Ess-a-Bagel', 'Queens', 'queens', 'food', 'Utopia Bagels in Queens still does it right - hand-rolled, boiled the old way, with that perfect crispy crust and chewy inside. The scallion cream cheese is made fresh and actually tastes like scallions.', 'Hand-rolled Queens bagels with scallion cream cheese that actually tastes right.', 'Go early on weekends before 10 a.m. or the line gets brutal. Cash or card both work now.', '7 to 111th Street in the Flushing and Whitestone direction. Worth the short trip from Manhattan.', 'Walk five minutes to a solid Colombian bakery for coffee - the combo is unbeatable.', 'Early on weekend mornings', 'After 10 a.m. on weekends when the line gets heavy', 'Classic breakfast pricing. Easy to justify an extra bagel for later.', '["bagels","breakfast","classic","queens"]', 1, NULL, NULL, NULL, NULL, NULL, 1, 1775699485813, 1775699485813);
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('The Cloisters', 'the-cloisters-washington-heights', 'A Medieval Castle in Upper Manhattan That Most Tourists Miss', 'Washington Heights', 'manhattan', 'museum', 'The Cloisters is a branch of the Met built from actual pieces of medieval European monasteries, reassembled on a hilltop in Fort Tryon Park overlooking the Hudson River. It sounds fake, but it''s real — Romanesque archways, Gothic chapels, a garden planted with species documented in medieval manuscripts. The Unicorn Tapestries alone are worth the trip.
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('DUMBO Archway', 'dumbo-archway-brooklyn', 'The Instagram Bridge Shot Everyone Takes (And a Better Spot Nearby)', 'DUMBO', 'brooklyn', 'view', 'You''ve seen the photo: the Manhattan Bridge perfectly framed through the brick buildings on Washington Street in DUMBO. It''s one of the most photographed spots in New York for a reason — it''s stunning. The Archway underneath the Manhattan Bridge overpass has become a gathering spot with markets, performances, and public art.
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('Abraço', 'abraco-east-village', 'Tiny East Village Espresso Bar With a Cult Following', 'East Village', 'manhattan', 'coffee', 'Abraço is barely bigger than a closet. There are maybe four seats. The espresso is flawless. That''s the whole pitch, and it''s been enough to make this one of the most beloved coffee shops in New York for over fifteen years. The olive oil cake is legendary — people write about it in food magazines.
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('Upstate Craft Beer & Oyster Bar', 'best-dollar-oysters-east-village', 'Best Dollar Oysters in the East Village', 'East Village', 'manhattan', 'food', '$1 oysters during happy hour that don''t suck? Yes, they still exist. The Wayland and similar East Village spots still do dollar oysters with solid cocktails in a chill Alphabet City vibe.', 'Dollar oysters and a cheap-drinks window that still feels worth knowing about.', 'Go weekdays from 4 to 7 p.m. Order a dozen and pair them with a cold beer or martini. It fills up fast once happy hour hits.', 'F/J/M/Z to Delancey-Essex or L to 1st Ave. Easy walk from the rest of the East Village.', 'Stroll over to a cheap Thai spot or dive bar afterward - it is a perfect cheap date-night combo.', 'Weekday happy hour from 4 to 7 p.m.', 'Right after work on Fridays if you want a seat without a wait', 'Dollar oysters during happy hour, then solid cocktails without wrecking the night.', '["oysters","happy-hour","cheap","east-village"]', 2, NULL, NULL, NULL, NULL, NULL, 1, 1775699485813, 1775699485813);
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('Prospect Park Long Meadow', 'prospect-park-long-meadow', 'Central Park Gets All the Press But This Brooklyn Park Is Better', 'Prospect Heights', 'brooklyn', 'park', 'Long Meadow in Prospect Park is a mile-long stretch of open grass that feels like actual countryside dropped into Brooklyn. Olmsted and Vaux — the same duo behind Central Park — designed this one too, and they considered it their masterpiece. On a sunny weekend, it fills with picnics, frisbee games, drum circles, and dogs running free in the morning hours.
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('Jackson Heights Food Crawl', 'jackson-heights-food-crawl-tourist-spot', 'Jackson Heights Food Crawl That Beats Any Tourist Spot', 'Queens', 'queens', 'food', 'If you only do one food crawl outside Manhattan, make it Jackson Heights. The whole point is that you can walk a few blocks and hit Colombian bakeries, Tibetan momo counters, Thai snacks, and random stalls that look better than most planned dinner reservations. It feels alive in a way a polished tourist food hall never can.
INSERT INTO spots (name, slug, title, neighborhood, borough, category, description, one_liner, pro_tip, subway, while_here, best_time, avoid_time, budget_note, vibe_tags, price_level, latitude, longitude, google_maps_url, photo_url, source, published, created_at, updated_at) VALUES ('PDT', 'pdt-east-village', 'A Speakeasy Hidden Inside a Hot Dog Shop in the East Village', 'East Village', 'manhattan', 'bar', 'PDT — Please Don''t Tell — is a cocktail bar hidden behind a phone booth inside Crif Dogs, a hot dog shop on St. Marks Place. You walk in, pick up the rotary phone, and if they have room, the back wall of the booth swings open into one of the best cocktail bars in New York. It''s theatrical and ridiculous and the drinks are genuinely excellent.
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'lic-landing-rooftop'), 'Best free view in the city. Took my girlfriend here, she loved it.', 'Carlos', 'Queens', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'lic-landing-rooftop'), 'Go on a Wednesday around 6pm. Half the crowd, same sunset.', 'Priya', 'Astoria', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'best-slice-brooklyn-after-midnight'), 'Best late-night slice in Brooklyn, hands down.', 'Alex', 'Williamsburg', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'best-slice-brooklyn-after-midnight'), 'The square slices hit different at 1am.', 'Maria', '', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'free-jazz-nights-harlem-locals-love'), 'Real Harlem jazz, not the tourist version.', 'Carlos', '', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'free-jazz-nights-harlem-locals-love'), 'Best night out uptown for under $20 total.', 'Priya', '', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'los-tacos-no-1-chelsea'), 'The adobada is non-negotiable. I''ve been coming here since they opened and it''s never let me down.', 'Mike', 'Hell''s Kitchen', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'los-tacos-no-1-chelsea'), 'Skip the line by going at 11:30 on a Tuesday. Three tacos, out in 10 minutes.', 'Daniela', 'Chelsea', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'best-bagel-nyc-not-ess-a-bagel'), 'Better than most Manhattan spots, no question.', 'David', '', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'best-bagel-nyc-not-ess-a-bagel'), 'Everything bagel with scallion is stupid good.', 'Alex', '', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'birria-landia-jackson-heights'), 'Came here at midnight after a concert. Best drunk food decision of my life.', 'Jordan', 'Bushwick', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'birria-landia-jackson-heights'), 'Bring cash and napkins. Lots of napkins. The consommé is everything.', 'Rosa', 'Jackson Heights', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'best-dollar-oysters-east-village'), 'Best $1 oyster deal left in Manhattan.', 'Sarah', '', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'best-dollar-oysters-east-village'), 'Go early or the good ones run out.', 'Mike', '', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'abraco-east-village'), 'The olive oil cake here changed my understanding of what cake can be. Not exaggerating.', 'Lena', 'East Village', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'jackson-heights-food-crawl-tourist-spot'), 'Do not build a perfect route. The best version is wandering and following the busiest counter each time.', 'Rafi', 'Jackson Heights', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'pdt-east-village'), 'Brought my parents here from Ohio. My dad picked up the phone and his face when the wall opened was priceless.', 'Sarah', 'Murray Hill', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'pdt-east-village'), 'The Benton''s Old Fashioned is still the best cocktail on the menu. Don''t sleep on it.', 'Dave', 'Williamsburg', 1, 1775699485813);
INSERT INTO spot_tips (spot_id, text, author_name, author_area, approved, created_at) VALUES ((SELECT id FROM spots WHERE slug = 'bemelmans-bar-upper-east-side'), 'Wore a blazer on a Tuesday night, had the whole banquette to myself. Felt like 1955 in the best way.', 'Marcus', 'Harlem', 1, 1775699485813);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('Williamsburg', 'williamsburg', 'brooklyn', 'Creative energy meets waterfront living. Brooklyn''s most famous neighborhood for good reason — cafes, vintage shops, and some of the best food in the city.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('East Village', 'east-village', 'manhattan', 'Punk rock roots with a modern edge. Dive bars next to ramen shops next to speakeasies. Still the most interesting neighborhood in Manhattan.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('Harlem', 'harlem', 'manhattan', 'Historic, musical, and full of neighborhood institutions. Go for jazz, soul food, brownstone blocks, and a pace that still feels lived in.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('Long Island City', 'long-island-city', 'queens', 'Waterfront Queens with Manhattan skyline views. Art galleries, breweries, and rooftop bars without the Manhattan price tag.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('Chelsea', 'chelsea', 'manhattan', 'Art galleries, the High Line, and Chelsea Market. A polished neighborhood that still knows how to have a good time.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('Jackson Heights', 'jackson-heights', 'queens', 'The most diverse neighborhood in the world, no exaggeration. Incredible food from every continent within a few blocks.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('DUMBO', 'dumbo', 'brooklyn', 'Cobblestone streets, bridge views, and waterfront parks. Touristy in the best spots but the locals know the quiet corners.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('Upper East Side', 'upper-east-side', 'manhattan', 'Museum Mile, classic bars, and old-money elegance. More interesting than people give it credit for — especially the quieter streets east of Lex.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('Washington Heights', 'washington-heights', 'manhattan', 'Dominican culture, Fort Tryon Park, and The Cloisters. One of Manhattan''s most underrated neighborhoods with incredible community energy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('Prospect Heights', 'prospect-heights', 'brooklyn', 'Brownstone Brooklyn at its best. Prospect Park, the Brooklyn Museum, and some of the coziest restaurants in the borough.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO neighborhoods (name, slug, borough, vibe, best_for, safety_notes, getting_around, stay_here_if, skip_if, photo_url, latitude, longitude) VALUES ('Bushwick', 'bushwick', 'brooklyn', 'Street art, warehouse parties, and the best late-night food in Brooklyn. Gritty, creative, and constantly evolving.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
